const crypto = require('crypto');
function b64uDecode(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return Buffer.from(s, 'base64').toString('utf8');
}
const item = $input.first().json;
const authHeader = item.headers?.authorization ?? '';
const token = authHeader.replace(/^Bearer\s+/i, '');
if (!token) throw new Error('401: Token eksik');
const parts = token.split('.');
if (parts.length !== 3) throw new Error('401: Geçersiz token');
const [header, payload, sig] = parts;
const expected = crypto.createHmac('sha256', $env.JWT_SECRET)
  .update(`${header}.${payload}`).digest('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
if (sig !== expected) throw new Error('401: Geçersiz imza');
const claims = JSON.parse(b64uDecode(payload));
if (claims.exp < Math.floor(Date.now() / 1000)) throw new Error('401: Token süresi dolmuş');
const body = item.body ?? {};
if (!body.draft_id) throw new Error('400: draft_id zorunlu');
return [{ json: { draft_id: body.draft_id, _sub: claims.sub } }];

// Faz 4: Twitter bağlı değil — draft'ı onaylar, Faz 5'te bu node Twitter'a gönderir
const draft = $input.first().json;
if (!draft?.id) throw new Error('404: Draft bulunamadı');
if (draft.status === 'published') throw new Error('409: Bu taslak zaten yayınlandı');
const jwtCtx = $('JWT Doğrula').first().json;
return [{ json: { draft_id: draft.id, client_id: draft.client_id, _sub: jwtCtx._sub } }];

const prev = $('Doğrula & Hazırla').first().json;
const esc = (s) => `'${String(s).replace(/'/g, "''")}'`;
const sql = `INSERT INTO audit_log (action, resource_type, resource_id, details)
VALUES ('publish', 'draft', ${esc(prev.draft_id)}, '{"note": "faz4_stub_twitter_not_connected"}'::jsonb);`;
